import{_ as e,o as a,c as d,ag as s}from"./chunks/framework.C9sp7nFj.js";const E=JSON.parse('{"title":"SetDIEdge 设置数字量输入边沿","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/SetDIEdge.md","filePath":"3. 指令/4. IO 指令/SetDIEdge.md","lastUpdated":1778862643000}'),i={name:"3. 指令/4. IO 指令/SetDIEdge.md"};function r(n,t,o,h,l,p){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="setdiedge-设置数字量输入边沿" tabindex="-1">SetDIEdge 设置数字量输入边沿 <a class="header-anchor" href="#setdiedge-设置数字量输入边沿" aria-label="Permalink to &quot;SetDIEdge 设置数字量输入边沿&quot;">​</a></h1><p>该指令用于强制设置某个数字量输入端口的边沿信号状态。在逻辑仿真或特定工艺调试中，通过此指令可以人为模拟信号的上升沿或下降沿触发，而无需物理信号的实际变化。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>SetDIEdge (DIN, EDGETYPE, VALUE)</code></p><p><code>SetDIEdge (数字量输入, 边沿类型, 强制值)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>DIN</td><td>DI</td><td>待强制边沿信号的目标数字量输入变量</td><td>必填</td></tr><tr><td>EDGETYPE</td><td>enum</td><td>边沿触发类型（<code>&quot;riseEdge&quot;</code>：上升沿，<code>&quot;fallEdge&quot;</code>：下降沿）</td><td>必填</td></tr><tr><td>VALUE</td><td>int 或 INT 变量</td><td>要在指定端口强制的边沿信号状态值（通常为 1 或 0）</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetDIEdge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DI9, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;riseEdge&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>强制 <strong>DI9</strong> 端口的上升沿信号为 <strong>1</strong> 状态。这通常会触发程序中所有关联该端口上升沿的逻辑判断或中断。</p>',13)])])}const g=e(i,[["render",r]]);export{E as __pageData,g as default};
